-- Source: MotherDuck thyroid_canonical_publication_v1_0.manuscript_workspace.ete_manuscript_analytic_v1
-- Captured: 2026-05-06 for THY-19 BQ migration

CREATE VIEW manuscript_workspace.ete_manuscript_analytic_v1 AS WITH path_event_fingerprint AS (SELECT h.path_event_fingerprint, m.* FROM main.canonical_path_malignant_events_v1 AS m INNER JOIN manuscript_workspace.path_malignant_event_fingerprint_v1 AS h ON ((m.rowid = h.path_malignant_rowid))), molecular_patient_dedup AS (SELECT * FROM manuscript_workspace.canonical_molecular_genetics_v2_braf_variant QUALIFY (row_number() OVER (PARTITION BY research_id ORDER BY test_date_native DESC NULLS LAST) = 1))SELECT p.research_id, p.path_surgery_id, g.surgery_episode_id_global, p.tumor_ordinal, p.specimen_id, p.synoptic_row_ix, (ptc.research_id IS NOT NULL) AS cohort_ptc, (cdf.research_id IS NOT NULL) AS cohort_descriptive_full, ((e.ete_grade IS NOT NULL) AND (g.surgery_episode_id_global IS NOT NULL) AND (g.surgery_episode_uid_source IN ('already_match', 'op_rebind')) AND (p.size_greatest_dimension_cm IS NOT NULL) AND (h.primary_histology_clean IS NOT NULL) AND (h.primary_histology_clean NOT IN ('NIFTP', 'FTUMP', 'follicular adenoma', 'atypical follicular / hurthle neoplasm', 'uncertain malignant potential (non-FTUMP)'))) AS analytic_eligible, p.extrathyroidal_extension AS ete_raw, e.ete_grade AS ete_norm, ddisc.gross_ete_effective, EXISTS(SELECT 1 FROM manuscript_workspace.cpm_ete_self_contradiction_queue_v1 AS q WHERE (q.research_id = p.research_id)) AS ete_cpm_self_contradiction_flag, h.primary_histology_clean AS primary_histology_trusted, v.histology_variant_clean AS histology_variant_trusted, p.size_greatest_dimension_cm AS size_greatest_dimension_cm_trusted, CASE  WHEN (COALESCE(szf.size_disagreement_any_flag, CAST('f' AS BOOLEAN))) THEN ('under_review') ELSE 'unflagged' END AS size_flag_queue_status, lat.derived_laterality_final AS laterality_trusted, (mfo.focality = 'multifocal') AS multifocal_flag, inv.vascular_invasion_clean AS vascular_invasion_trusted, inv.lymphatic_invasion_clean AS lymphatic_invasion_trusted, inv.perineural_invasion_clean AS perineural_invasion_trusted, ln.ln_path_examined AS ln_examined_total, ln.ln_path_positive AS ln_positive_total, (NOT COALESCE(lnf.ln_denom_missing_any_flag, CAST('f' AS BOOLEAN))) AS ln_denominator_reliable_flag, ddisc.reported_t_stage_ajcc8, ddisc.derived_t_stage_ajcc8, ddisc.discordance_t_stage_flag AS t_stage_discordance_flag, COALESCE(p.overall_stage_ajcc8, p.overall_stage_ajcc7) AS ajcc_overall_stage_trusted, op.procedure_normalized_trusted, op.surgery_date_native AS surgery_date_native, op.laterality AS surgery_laterality_trusted, fna.bethesda_final_recomputed AS max_preop_bethesda, mol.braf_variant_derived, mol.ras_flag, mol.tert_flag, mol.ret_fusion_flag, rc.any_recurrence_final AS recurrence_ever_trusted, CASE  WHEN (((mc.first_surgery_date IS NOT NULL) AND (mc.recurrence_date IS NOT NULL))) THEN (date_diff('day', CAST(mc.first_surgery_date AS DATE), CAST(mc.recurrence_date AS DATE))) ELSE NULL END AS days_to_first_recurrence, cpm.last_contact_date AS last_known_alive_date, cpm.vital_status AS vital_status_trusted, 'manuscript_workspace.ete_manuscript_analytic_v1: 9 path_fp helpers + path_event_discordance_dedup_ete_v1' AS ete_source_table, CAST(CURRENT_TIMESTAMP AS TIMESTAMP) AS build_ts FROM path_event_fingerprint AS p LEFT JOIN manuscript_workspace.path_malignant_overlay_ete_clean_w_fp_v1 AS e ON ((p.path_event_fingerprint = e.path_event_fingerprint)) LEFT JOIN manuscript_workspace.path_malignant_overlay_global_epi_w_fp_v1 AS g ON ((p.path_event_fingerprint = g.path_event_fingerprint)) LEFT JOIN manuscript_workspace.path_malignant_overlay_histology_w_fp_v1 AS h ON ((p.path_event_fingerprint = h.path_event_fingerprint)) LEFT JOIN manuscript_workspace.path_malignant_overlay_variant_w_fp_v1 AS v ON ((p.path_event_fingerprint = v.path_event_fingerprint)) LEFT JOIN manuscript_workspace.path_malignant_overlay_size_flag_w_fp_v1 AS szf ON ((p.path_event_fingerprint = szf.path_event_fingerprint)) LEFT JOIN manuscript_workspace.path_malignant_overlay_laterality_w_fp_v1 AS lat ON ((p.path_event_fingerprint = lat.path_event_fingerprint)) LEFT JOIN manuscript_workspace.path_malignant_overlay_invasion_w_fp_v1 AS inv ON ((p.path_event_fingerprint = inv.path_event_fingerprint)) LEFT JOIN manuscript_workspace.path_malignant_overlay_ln_denom_w_fp_v1 AS lnf ON ((p.path_event_fingerprint = lnf.path_event_fingerprint)) LEFT JOIN manuscript_workspace.path_event_discordance_dedup_ete_v1 AS ddisc ON ((p.path_event_fingerprint = ddisc.path_event_fingerprint)) LEFT JOIN manuscript_workspace.path_episode_multifocality_v1 AS mfo ON (((p.research_id = mfo.research_id) AND (mfo.surgery_episode_uid = CAST(g.surgery_episode_id_global AS VARCHAR)))) LEFT JOIN main.canonical_operative_events_v1 AS op0 ON (((op0.surgery_episode_id = g.surgery_episode_id_global) AND (op0.research_id = p.research_id))) LEFT JOIN manuscript_workspace.canonical_operative_events_v1_rule_clean AS op ON (((op0.research_id = op.research_id) AND (op0.surgery_episode_id = op.surgery_episode_id))) LEFT JOIN manuscript_workspace.ln_per_patient_multisource_v1 AS ln ON ((CAST(p.research_id AS VARCHAR) = ln.research_id)) LEFT JOIN manuscript_workspace.canonical_fna_patient_rollup_v1_clean AS fna ON ((p.research_id = fna.research_id)) LEFT JOIN molecular_patient_dedup AS mol ON ((p.research_id = mol.research_id)) LEFT JOIN manuscript_workspace.manuscript_cohort_v1_recurrence_clean AS rc ON ((p.research_id = rc.research_id)) LEFT JOIN main.manuscript_cohort_v1 AS mc ON ((p.research_id = mc.research_id)) LEFT JOIN main.canonical_patient_master AS cpm ON ((p.research_id = cpm.research_id)) LEFT JOIN manuscript_workspace.qc_manuscript_cohort_v2_ptc AS ptc ON ((p.research_id = ptc.research_id)) LEFT JOIN manuscript_workspace.cohort_descriptive_full_cohort_v1 AS cdf ON ((p.research_id = cdf.research_id));
